class Program {
    static void Main() {
        // Define the allocation percentages for different asset classes
        double[] allocations = {0.35, 0.45, 0.18, 0.02};

        // Calculate the total percentage of the portfolio
        double totalPercentage = allocations.Sum();

        // Ensure the sum is close enough to 1 (or 100%)
        if (Math.Abs(totalPercentage - 1) > 0.01) {
            Console.WriteLine("The sum of the allocation percentages does not match 100%. Please adjust.");
            return;
        }

        // Print out the recommended asset allocation
        foreach (var allocation in allocations) {
            Console.WriteLine($"Allocate {allocation * 100}% to this asset class.");
        }
    }
}
```

